-- +goose Up
-- Ironman Planner: initial schema (PostgreSQL >= 15).
--
-- Ported from docs/arquitetura/schema.sql (SQLite dialect) following the
-- decisions in docs/04-arquitetura.md sections 8 and 9:
--   * ids stay TEXT (ULID generated by the application);
--   * timestamps become timestamptz, JSON becomes jsonb, flags become boolean;
--   * xp and kill counts become bigint;
--   * users are identified by the OIDC subject (Zitadel) or a fixed dev subject
--     when AUTH_MODE=dev; there is no password column;
--   * `sessions` matches the table layout expected by alexedwards/scs pgxstore,
--     so the HTTP layer can use it directly or with a custom store;
--   * `sync_runs.trigger` was renamed to `trigger_kind` (TRIGGER is a keyword);
--   * `settings` uses UNIQUE NULLS NOT DISTINCT so a NULL account_id means "global".
--
-- Table names are the same as in schema.sql so the docs keep applying.

------------------------------------------------------------------------------
-- 1. Identity and access
------------------------------------------------------------------------------
CREATE TABLE users (
  id            TEXT PRIMARY KEY,
  subject       TEXT NOT NULL UNIQUE,          -- OIDC `sub` (Zitadel) or 'dev' in AUTH_MODE=dev
  issuer        TEXT,                          -- OIDC issuer URL; NULL in dev mode
  username      TEXT NOT NULL UNIQUE,          -- preferred_username claim or 'dev'
  email         TEXT,
  display_name  TEXT,
  role          TEXT NOT NULL DEFAULT 'owner' CHECK (role IN ('owner','member')),
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_login_at TIMESTAMPTZ
);
COMMENT ON TABLE users IS 'Application users; one row per OIDC subject (or the single dev user).';

-- Layout required by github.com/alexedwards/scs/pgxstore. `data` holds the
-- gob-encoded session (user id, OIDC tokens hash, CSRF, ...).
CREATE TABLE sessions (
  token  TEXT PRIMARY KEY,
  data   BYTEA NOT NULL,
  expiry TIMESTAMPTZ NOT NULL
);
CREATE INDEX sessions_expiry_idx ON sessions (expiry);
COMMENT ON TABLE sessions IS 'HTTP sessions (scs pgxstore layout). Cleaned up by the session manager.';

-- API tokens for scripts, CLI and MCP (`Authorization: Bearer apk_...`).
CREATE TABLE api_tokens (
  id           TEXT PRIMARY KEY,
  user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash   TEXT NOT NULL UNIQUE,           -- sha256 of the token, shown once
  label        TEXT,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_used_at TIMESTAMPTZ,
  revoked_at   TIMESTAMPTZ
);
CREATE INDEX api_tokens_user_idx ON api_tokens (user_id);
COMMENT ON TABLE api_tokens IS 'Bearer tokens for the CLI/MCP clients (not for the Microbot plugin).';

------------------------------------------------------------------------------
-- 2. Game accounts
------------------------------------------------------------------------------
CREATE TABLE accounts (
  id             TEXT PRIMARY KEY,
  user_id        TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  rsn            TEXT NOT NULL,                -- current name as shown on hiscores
  rsn_normalized TEXT NOT NULL,                -- lower-case, spaces -> '_' (lookup key)
  mode           TEXT NOT NULL CHECK (mode IN ('ironman','hcim','uim','gim')),
  guide_id       TEXT NOT NULL,                -- active guide (content/)
  layer          TEXT NOT NULL DEFAULT 'enhanced' CHECK (layer IN ('classic','enhanced')),
  wom_player_id  BIGINT,                       -- Wise Old Man id, when linked
  name_history   JSONB NOT NULL DEFAULT '[]'::jsonb, -- [{rsn, from, to, detected_by}]
  active         BOOLEAN NOT NULL DEFAULT true,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (user_id, rsn_normalized)
);
COMMENT ON TABLE accounts IS 'OSRS accounts tracked by a user. One user may track several accounts.';

-- Settings: account_id NULL = global. NULLS NOT DISTINCT makes the NULL row unique too.
CREATE TABLE settings (
  account_id TEXT REFERENCES accounts(id) ON DELETE CASCADE,
  key        TEXT NOT NULL,
  value      JSONB NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE NULLS NOT DISTINCT (account_id, key)
);
COMMENT ON TABLE settings IS 'Key/value settings; account_id NULL means global.';

-- Microbot/RuneLite plugin tokens: one per client install, scope = one account.
CREATE TABLE plugin_ingest_tokens (
  id               TEXT PRIMARY KEY,
  account_id       TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  token_hash       TEXT NOT NULL UNIQUE,       -- sha256 of the 'ipl_...' token (shown once)
  label            TEXT,                       -- 'desktop', 'laptop'
  scopes           JSONB NOT NULL DEFAULT '["vars","skills","collection_log"]'::jsonb, -- 'bank','inventory','equipment' are opt-in
  manifest_version INTEGER NOT NULL DEFAULT 0, -- last manifest version delivered to this client
  last_seq         BIGINT NOT NULL DEFAULT 0,  -- last accepted client_seq (idempotency/order)
  last_seen_at     TIMESTAMPTZ,
  last_ip          TEXT,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  revoked_at       TIMESTAMPTZ
);
CREATE INDEX pit_account_idx ON plugin_ingest_tokens (account_id);
COMMENT ON TABLE plugin_ingest_tokens IS 'Bearer tokens used by the Microbot plugin to push snapshots (docs/06).';

------------------------------------------------------------------------------
-- 3. Sync and snapshots (append-only)
------------------------------------------------------------------------------
CREATE TABLE sync_runs (
  id              TEXT PRIMARY KEY,
  account_id      TEXT REFERENCES accounts(id) ON DELETE CASCADE, -- NULL for global jobs (wiki bucket)
  source          TEXT NOT NULL CHECK (source IN ('hiscores','wom','wikisync','plugin','wiki_bucket','import')),
  trigger_kind    TEXT NOT NULL CHECK (trigger_kind IN ('scheduled','manual','push','boot')),
  status          TEXT NOT NULL CHECK (status IN ('queued','running','ok','unchanged','skipped','rate_limited','error')),
  started_at      TIMESTAMPTZ,
  finished_at     TIMESTAMPTZ,
  http_status     INTEGER,
  error           TEXT,
  snapshot_id     TEXT,                        -- set when a new snapshot was produced
  steps_changed   INTEGER NOT NULL DEFAULT 0,  -- how many steps changed status on re-evaluation
  next_allowed_at TIMESTAMPTZ,                 -- backoff after 429/5xx
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX sync_runs_account_source_idx ON sync_runs (account_id, source, created_at DESC);
COMMENT ON TABLE sync_runs IS 'One row per sync attempt (scheduler, manual, plugin push).';

CREATE TABLE snapshots (
  id              TEXT PRIMARY KEY,
  account_id      TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  source          TEXT NOT NULL CHECK (source IN ('hiscores','wom','wikisync','plugin','import')),
  kind            TEXT NOT NULL DEFAULT 'full' CHECK (kind IN ('full','delta')),
  fetched_at      TIMESTAMPTZ NOT NULL,
  raw             JSONB NOT NULL,              -- payload as received (re-processable)
  raw_hash        TEXT NOT NULL,               -- sha256(raw) for dedupe
  adapter_version INTEGER NOT NULL,            -- normalizer version used
  client_seq      BIGINT,                      -- plugin only
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (account_id, source, raw_hash)
);
CREATE INDEX snapshots_account_time_idx ON snapshots (account_id, fetched_at DESC);
CREATE INDEX snapshots_account_source_time_idx ON snapshots (account_id, source, fetched_at DESC);
COMMENT ON TABLE snapshots IS 'Immutable raw snapshots per source. Normalized rows live in snapshot_* tables.';

-- Normalized per-snapshot tables (history; feed charts and diffs).
CREATE TABLE snapshot_skills (
  snapshot_id TEXT NOT NULL REFERENCES snapshots(id) ON DELETE CASCADE,
  skill       TEXT NOT NULL,
  level       INTEGER NOT NULL,
  xp          BIGINT,
  rank        BIGINT,
  boosted     INTEGER,                         -- plugin only (boosted level)
  PRIMARY KEY (snapshot_id, skill)
);

CREATE TABLE snapshot_activities (               -- bosses, clues, minigames, raids
  snapshot_id TEXT NOT NULL REFERENCES snapshots(id) ON DELETE CASCADE,
  activity    TEXT NOT NULL,                   -- canonical hiscores name
  score       BIGINT NOT NULL,                 -- -1 = unranked
  rank        BIGINT,
  PRIMARY KEY (snapshot_id, activity)
);

CREATE TABLE snapshot_quests (
  snapshot_id TEXT NOT NULL REFERENCES snapshots(id) ON DELETE CASCADE,
  quest       TEXT NOT NULL,                   -- canonical wiki name
  state       TEXT NOT NULL CHECK (state IN ('NOT_STARTED','IN_PROGRESS','FINISHED')),
  PRIMARY KEY (snapshot_id, quest)
);

CREATE TABLE snapshot_diary_tasks (
  snapshot_id TEXT NOT NULL REFERENCES snapshots(id) ON DELETE CASCADE,
  area        TEXT NOT NULL,
  tier        TEXT NOT NULL CHECK (tier IN ('easy','medium','hard','elite')),
  task_index  INTEGER NOT NULL,
  done        BOOLEAN NOT NULL,
  PRIMARY KEY (snapshot_id, area, tier, task_index)
);

CREATE TABLE snapshot_combat_achievements (
  snapshot_id TEXT NOT NULL REFERENCES snapshots(id) ON DELETE CASCADE,
  ca_id       INTEGER NOT NULL,
  done        BOOLEAN NOT NULL,
  PRIMARY KEY (snapshot_id, ca_id)
);

CREATE TABLE snapshot_collection_log (
  snapshot_id TEXT NOT NULL REFERENCES snapshots(id) ON DELETE CASCADE,
  item_id     INTEGER NOT NULL,
  qty         INTEGER NOT NULL DEFAULT 1,
  PRIMARY KEY (snapshot_id, item_id)
);

CREATE TABLE snapshot_vars (
  snapshot_id TEXT NOT NULL REFERENCES snapshots(id) ON DELETE CASCADE,
  kind        TEXT NOT NULL CHECK (kind IN ('varbit','varp')),
  var_id      INTEGER NOT NULL,
  value       INTEGER NOT NULL,
  PRIMARY KEY (snapshot_id, kind, var_id)
);

CREATE TABLE snapshot_items (                    -- bank/inventory/equipment (opt-in)
  snapshot_id TEXT NOT NULL REFERENCES snapshots(id) ON DELETE CASCADE,
  container   TEXT NOT NULL CHECK (container IN ('bank','inventory','equipment','poh')),
  item_id     INTEGER NOT NULL,
  qty         INTEGER NOT NULL,
  PRIMARY KEY (snapshot_id, container, item_id)
);

------------------------------------------------------------------------------
-- 4. Merged current state (rule engine input)
------------------------------------------------------------------------------
-- One row per known fact. Sources cover different facets; the merge is
-- "last observation wins" within a facet, with source priority on timestamp
-- ties (plugin > wikisync > hiscores > wom). The priority is applied by the
-- application before writing.
CREATE TABLE player_state (
  account_id  TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  facet       TEXT NOT NULL CHECK (facet IN ('skill','activity','quest','diary_task','combat_achievement','collection_log','varbit','varp','item')),
  key         TEXT NOT NULL,                   -- 'agility' | 'Zulrah' | 'Lost City' | 'Ardougne:easy:3' | '12345' | 'bank:4151'
  value       JSONB NOT NULL,                  -- {"level":56,"xp":...} | {"score":120} | {"state":"FINISHED"} | {"done":true} | {"qty":1} | {"value":1}
  source      TEXT NOT NULL,
  snapshot_id TEXT NOT NULL REFERENCES snapshots(id),
  observed_at TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (account_id, facet, key)
);
CREATE INDEX player_state_observed_idx ON player_state (account_id, facet, observed_at);
CREATE INDEX player_state_value_gin_idx ON player_state USING gin (value jsonb_path_ops);
COMMENT ON TABLE player_state IS 'Current merged fact per (account, facet, key). Rewritten after every snapshot.';

------------------------------------------------------------------------------
-- 5. Loaded content (index; the source of truth is content/ in git)
------------------------------------------------------------------------------
CREATE TABLE content_versions (
  id            TEXT PRIMARY KEY,
  content_hash  TEXT NOT NULL UNIQUE,          -- sha256 of the canonical bundle
  git_sha       TEXT,
  guide_version TEXT,
  loaded_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  step_count    INTEGER NOT NULL
);
COMMENT ON TABLE content_versions IS 'Every content bundle that was ever loaded by `ironman serve`.';

CREATE TABLE content_steps (                     -- one per step of the currently loaded guide
  step_id            TEXT PRIMARY KEY,
  guide_id           TEXT NOT NULL,
  section_id         TEXT NOT NULL,
  position           INTEGER NOT NULL,         -- global order in the guide
  rule_hash          TEXT NOT NULL,            -- sha256(canonical complete_when); change => re-evaluate
  is_manual          BOOLEAN NOT NULL,
  layers             JSONB NOT NULL,
  modes              JSONB NOT NULL,
  content_version_id TEXT NOT NULL REFERENCES content_versions(id)
);
CREATE INDEX content_steps_guide_idx ON content_steps (guide_id, position);

-- ID remapping declared in content/migrations/*.json (replaces).
CREATE TABLE step_id_aliases (
  old_step_id TEXT PRIMARY KEY,
  new_step_id TEXT NOT NULL,
  applied_at  TIMESTAMPTZ
);

------------------------------------------------------------------------------
-- 6. Progress per account
------------------------------------------------------------------------------
CREATE TABLE step_progress (
  account_id           TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  step_id              TEXT NOT NULL,          -- no FK: progress survives steps removed from content
  status               TEXT NOT NULL CHECK (status IN ('pending','auto_done','manual_done','skipped')),
  completed_at         TIMESTAMPTZ,
  evidence_snapshot_id TEXT REFERENCES snapshots(id),
  evidence             JSONB,                  -- [{rule, observed, satisfied, source, observed_at}]
  rule_hash            TEXT,                   -- hash of the rule that produced auto_done
  manual_locked        BOOLEAN NOT NULL DEFAULT false, -- true = user pinned the status; engine must not touch it
  manual_at            TIMESTAMPTZ,
  regressed_at         TIMESTAMPTZ,            -- engine saw the rule stop holding after auto_done
  user_note            TEXT,
  updated_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (account_id, step_id)
);
CREATE INDEX step_progress_status_idx ON step_progress (account_id, status);
COMMENT ON TABLE step_progress IS 'Status of each guide step per account. auto_done always carries evidence.';

-- Transition history (feeds "what got unlocked/completed today").
CREATE TABLE step_progress_events (
  id          TEXT PRIMARY KEY,
  account_id  TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  step_id     TEXT NOT NULL,
  from_status TEXT,
  to_status   TEXT NOT NULL,
  cause       TEXT NOT NULL CHECK (cause IN ('engine','user','migration','import')),
  snapshot_id TEXT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX spe_account_time_idx ON step_progress_events (account_id, created_at DESC);

CREATE TABLE goals (
  id          TEXT PRIMARY KEY,
  account_id  TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  ref         TEXT NOT NULL,                   -- 'quest:Dragon Slayer II' | 'item:Barrows gloves' | 'skill:agility:70' | 'step:1.5.21'
  label       TEXT NOT NULL,
  priority    INTEGER NOT NULL DEFAULT 100,
  status      TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','achieved','abandoned')),
  plan_cache  JSONB,                           -- last computed topological plan
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  achieved_at TIMESTAMPTZ
);
CREATE INDEX goals_account_idx ON goals (account_id, status, priority);

------------------------------------------------------------------------------
-- 7. External caches
------------------------------------------------------------------------------
CREATE TABLE wiki_cache (                        -- Bucket API and other reference data
  kind       TEXT NOT NULL CHECK (kind IN ('quest','diary','item','boss','varbit_map','ca')),
  key        TEXT NOT NULL,                     -- canonical name
  value      JSONB NOT NULL,                    -- normalized by the adapter
  fetched_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  etag       TEXT,
  PRIMARY KEY (kind, key)
);

CREATE TABLE graph_cache (
  id                 TEXT PRIMARY KEY,
  content_version_id TEXT NOT NULL REFERENCES content_versions(id),
  wiki_fingerprint   TEXT NOT NULL,            -- hash of the wiki_cache rows used
  built_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
  nodes_json         JSONB NOT NULL,
  edges_json         JSONB NOT NULL
);

------------------------------------------------------------------------------
-- 8. Convenience views
------------------------------------------------------------------------------
CREATE VIEW v_current_skills AS
  SELECT account_id,
         key AS skill,
         (value->>'level')::integer AS level,
         (value->>'xp')::bigint     AS xp,
         source,
         observed_at
  FROM player_state
  WHERE facet = 'skill';

CREATE VIEW v_current_quests AS
  SELECT account_id,
         key AS quest,
         value->>'state' AS state,
         source,
         observed_at
  FROM player_state
  WHERE facet = 'quest';

CREATE VIEW v_step_board AS                      -- what the UI lists
  SELECT cs.guide_id, cs.section_id, cs.position, cs.step_id, cs.is_manual,
         sp.account_id,
         COALESCE(sp.status, 'pending') AS status,
         sp.completed_at, sp.manual_locked, sp.regressed_at
  FROM content_steps cs
  LEFT JOIN step_progress sp ON sp.step_id = cs.step_id;

-- +goose Down
DROP VIEW IF EXISTS v_step_board;
DROP VIEW IF EXISTS v_current_quests;
DROP VIEW IF EXISTS v_current_skills;

DROP TABLE IF EXISTS graph_cache;
DROP TABLE IF EXISTS wiki_cache;
DROP TABLE IF EXISTS goals;
DROP TABLE IF EXISTS step_progress_events;
DROP TABLE IF EXISTS step_progress;
DROP TABLE IF EXISTS step_id_aliases;
DROP TABLE IF EXISTS content_steps;
DROP TABLE IF EXISTS content_versions;
DROP TABLE IF EXISTS player_state;
DROP TABLE IF EXISTS snapshot_items;
DROP TABLE IF EXISTS snapshot_vars;
DROP TABLE IF EXISTS snapshot_collection_log;
DROP TABLE IF EXISTS snapshot_combat_achievements;
DROP TABLE IF EXISTS snapshot_diary_tasks;
DROP TABLE IF EXISTS snapshot_quests;
DROP TABLE IF EXISTS snapshot_activities;
DROP TABLE IF EXISTS snapshot_skills;
DROP TABLE IF EXISTS snapshots;
DROP TABLE IF EXISTS sync_runs;
DROP TABLE IF EXISTS plugin_ingest_tokens;
DROP TABLE IF EXISTS settings;
DROP TABLE IF EXISTS accounts;
DROP TABLE IF EXISTS api_tokens;
DROP TABLE IF EXISTS sessions;
DROP TABLE IF EXISTS users;
